from pathlib import Path
import base64, hashlib, subprocess, sys, zlib

root = Path(sys.argv[1]).resolve()
payload = ""
patch = zlib.decompress(base64.b64decode(payload))
expected = "7c53576eb95e75a86ba2fe0323112e7df6ca9e0df0d2e4b9d8ae5f4e8d49461"
actual = hashlib.sha256(patch).hexdigest()
if actual != expected:
    raise RuntimeError(f"alpha42 patch checksum mismatch: {actual} != {expected}")

subprocess.run(["git", "-C", str(root), "apply", "--whitespace=nowarn", "-"], input=patch, check=True)
print("PKVault V8 alpha42 full quest/playtime/daily reroll pass applied")
